module comparator_4bit(
    input [3:0] A, B,
    output A_greater, A_equal, A_less
);
// Combinational logic for comparison
wire [3:0] diff;
wire [3:0] borrow;
assign diff = A - B;
assign borrow = ~A + 1 + B;
assign A_greater = (&diff) && !borrow[3];
assign A_equal = !(|diff);
assign A_less = borrow[3];
endmodule
